export function ImportWizard({
  step = "{{step}}",
  fileName = "{{fileName}}",
  rowCount = {{rowCount}},
  accent = "{{accent}}",
}) {
  const steps = [["upload", "1 Upload"], ["map", "2 Map fields"], ["confirm", "3 Confirm"]];
  const panels = {
    upload: <>Selected file: <strong>{fileName}</strong></>,
    map: <>Map columns from {fileName} to fields ({rowCount} rows)</>,
    confirm: <>Ready to import {rowCount} rows from {fileName}</>,
  };
  return (
    <div style={{ font: "12px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 16, borderRadius: 12, width: 300, boxSizing: "border-box" }}>
      <div style={{ display: "flex", gap: 6, marginBottom: 14 }}>
        {steps.map(([id, label]) => (
          <span key={id} style={{ flex: 1, textAlign: "center", padding: "7px 4px", borderRadius: 6, fontSize: 10, fontWeight: 600, background: id === step ? accent : "#24143010" }}>{label}</span>
        ))}
      </div>
      <div style={{ padding: 14, borderRadius: 8, background: "#ffffff", border: "1.5px solid #24143018", textAlign: "center" }}>{panels[step]}</div>
    </div>
  );
}
